display.text:
const sequelize = require('../../database/sequelize');

function cosineSimilarity(a, b) {
    let dot = 0, na = 0, nb = 0;
    for (let i = 0; i < a.length; i++) {
        dot += a[i] * b[i];
        na += a[i] * a[i];
        nb += b[i] * b[i];
    }
    return dot / (Math.sqrt(na) * Math.sqrt(nb));
}

async function recognize(req, res) {
    const { id: programmeId } = req.params;
    const { image } = req.body;

    if (!image || typeof image !== 'string') {
        return res.status(400).json({ error: 'Missing or invalid image base64 in request body' });
    }

    try {
        const imageBuffer = Buffer.from(image, 'base64');

        const { getFaceEmbeddings } = await import('../../modules/facial_recog/facenetClient.js');
        const faces = await getFaceEmbeddings(imageBuffer);

        if (faces.length === 0) {
            return res.json({ matches: [] });
        }

        const [embeddings] = await sequelize.query(`
            SELECT fe."userId", fe.embeddings, u."enName" AS user_name
            FROM "faceEmbeddings" fe
            JOIN "users" u ON u.id = fe."userId"
            WHERE fe."imageType" = 'primary'
        `);

        const [delegates] = await sequelize.query(`
            SELECT d.id, d.name
            FROM delegates d
            JOIN programme_delegates pd ON pd.delegate_id = d.id
            WHERE pd.programme_id = $1
        `, { bind: [programmeId] });

        const THRESHOLD = 0.5;
        const seen = new Set();
        const matches = [];

        for (const face of faces) {
            for (const emb of embeddings) {
                const storedEmb = JSON.parse(emb.embeddings);
                const similarity = cosineSimilarity(face.embedding, storedEmb);

                if (similarity >= THRESHOLD) {
                    const delegate = delegates.find(d => d.name === emb.user_name);
                    if (delegate && !seen.has(delegate.id)) {
                        seen.add(delegate.id);
                        matches.push({
                            delegateId: delegate.id,
                            name: emb.user_name,
                            confidence: Math.round(similarity * 100) / 100,
                        });
                    }
                }
            }
        }

        matches.sort((a, b) => b.confidence - a.confidence);
        res.json({ matches });
    } catch (err) {
        console.error('[Recognize]', err);
        res.status(500).json({ error: err.message });
    }
}

module.exports = { recognize };

